#include <stdio.h>

static inline int square_int(int value) {
    return value * value;
}

#define SQUARE_MACRO(x) ((x) * (x))

int main(void) {
    int i = 3;
    int safe = square_int(i++);

    printf("safe=%d i=%d\n", safe, i);
    printf("macro with a plain value=%d\n", SQUARE_MACRO(i));
    return 0;
}

